package com.campusradar.accountdata;

import com.campusradar.common.*;
import com.campusradar.resume.PrivateFileStorage;
import com.campusradar.task.TaskService;
import java.nio.file.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.jdbc.datasource.*;
import tools.jackson.databind.json.JsonMapper;
import static com.campusradar.common.SqlRows.map;
import static org.junit.jupiter.api.Assertions.*;

/** Exercise the complete private projection with the full schema foreign keys enabled. */
class AccountDataTasksTest {
    @TempDir Path filesRoot;
    final Clock clock=Clock.fixed(Instant.parse("2026-10-29T08:00:00Z"),ZoneOffset.UTC);
    final String owner=UUID.randomUUID().toString(),other=UUID.randomUUID().toString();
    JdbcTemplate db;SqlRows rows;PrivateSnapshot snapshots;BackupCodec codec;PrivateFileStorage storage;AccountDataService service;AccountDataTasks worker;
    @BeforeEach void setup() throws Exception {
        var source=new DriverManagerDataSource("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;NON_KEYWORDS=YEAR;DB_CLOSE_DELAY=-1","sa","");
        db=new JdbcTemplate(source);
        // H2 adaptations are limited to physical MySQL storage/index syntax. Keep all ownership FKs/checks.
        String sql=Files.readString(Path.of("../docs/contracts/schema.sql"))
            .replaceAll("(?m)^\\s*--.*$","").replaceAll("COMMENT\\s*'[^']*'","")
            .replaceAll("CHARACTER SET ascii COLLATE ascii_bin","")
            .replaceAll("\\) ENGINE=InnoDB[^;]*;",");")
            .replaceAll("(?m)^\\s*(?:FULLTEXT )?KEY [^\\n]*\\n","")
            .replaceAll("UNIQUE KEY ","CONSTRAINT ").replaceAll("(CONSTRAINT \\w+) \\(","$1 UNIQUE (")
            .replaceAll(" ON UPDATE CURRENT_TIMESTAMP\\(3\\)","").replace(" STORED","")
            .replaceAll("\\bJSON\\b","VARCHAR(10000000)").replaceAll(" AFTER job_id","")
            .replaceAll(",\\s*\\)",")");
        for(String statement:sql.split(";")){
            statement=statement.trim();if(statement.isEmpty()||statement.startsWith("SET "))continue;
            db.execute(statement);
        }
        var mapper=JsonMapper.builder().build();rows=new SqlRows(new NamedParameterJdbcTemplate(source),mapper);var manager=new DataSourceTransactionManager(source);storage=new PrivateFileStorage(filesRoot.toString());codec=new BackupCodec(mapper,clock,Base64.getEncoder().encodeToString(new byte[32]),"","test");snapshots=new PrivateSnapshot(rows,manager,clock);service=new AccountDataService(rows,new OwnerTransactions(rows,manager),new ContractInputs(mapper),new TaskService(rows,clock),codec,storage,clock,snapshots);worker=new AccountDataTasks(rows,snapshots,service,codec,storage,clock,manager);
        for(String user:List.of(owner,other))insert("users",map("id",user,"email",user+"@example.test","password_hash","secret","display_name","测试用户","status","ACTIVE","preferences","{\"roles\":[],\"cities\":[],\"recruitmentTypes\":[],\"graduationYear\":null}","timezone","Asia/Shanghai"));
    }
    void insert(String table,Map<String,Object> data){rows.db.update("INSERT INTO "+table+"("+String.join(",",data.keySet())+") VALUES("+String.join(",",data.keySet().stream().map(k->":"+k).toList())+")",data);}
    String file(String purpose,byte[] bytes){String id=UUID.randomUUID().toString(),key=owner+"/"+id+".bin";storage.move(storage.stage(bytes),key);insert("files",map("id",id,"user_id",owner,"purpose",purpose,"original_name",purpose.equals("BACKUP")?"backup.zip":"original.txt","storage_key",key,"mime_type",purpose.equals("BACKUP")?"application/zip":"text/plain","size_bytes",bytes.length,"sha256",PrivateFileStorage.hash(bytes)));return id;}
    String resume(){String f=file("RESUME","original".getBytes()),id=UUID.randomUUID().toString();insert("resumes",map("id",id,"user_id",owner,"file_id",f,"name","简历","sequence",1,"is_default",true,"text_content","教育与经历","extraction_state","TEXT_READY"));return id;}
    String plan(String user,String title){String id=UUID.randomUUID().toString();insert("plan_tasks",map("id",id,"user_id",user,"title",title,"status","TODO","notes","","milestone",""));return id;}
    Map<String,Object> lease(String type,Map<String,Object> payload){String id=UUID.randomUUID().toString(),token=UUID.randomUUID().toString();insert("tasks",map("id",id,"user_id",owner,"type",type,"state","RUNNING","payload",rows.json.writeValueAsString(payload),"dedup_key",UUID.randomUUID().toString(),"next_attempt_at",Timestamp.from(clock.instant()),"lease_token",token,"lease_until",Timestamp.from(clock.instant().plusSeconds(300))));var out=new LinkedHashMap<>(payload);out.put("taskId",id);out.put("leaseToken",token);return out;}
    BackupCodec.Archive capture(boolean originals){var c=snapshots.capture(owner);var bytes=new HashMap<String,byte[]>();if(originals)for(var f:c.storage().values())bytes.put(f.get("id").toString(),storage.read(f.get("storageKey").toString(),((Number)f.get("sizeBytes")).longValue(),f.get("sha256").toString()));return codec.decode(owner,codec.encode(owner,c.data(),c.files(),bytes,originals));}
    String backup(boolean originals){var a=capture(originals);return file("BACKUP",codec.encode(owner,a.data(),(List<Map<String,Object>>)a.manifest().get("files"),a.files(),originals));}
    @SuppressWarnings("unchecked") Map<String,Object> preview(String file){return (Map<String,Object>)service.preview(owner,Map.of("fileId",file),UUID.randomUUID().toString());}
    @Test void exportIsSignedScopedAndReplayReturnsSameFile(){resume();plan(owner,"准备面试");var p=lease("DATA_EXPORT",Map.of("includeFiles",true));String result=worker.execute("DATA_EXPORT",owner,p);assertEquals(result,worker.execute("DATA_EXPORT",owner,p));var a=service.archive(owner,result);assertEquals(2,snapshots.recordCount(a));assertEquals(1,a.files().size());assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM files WHERE user_id=?",Integer.class,owner));assertThrows(ApiProblem.class,()->service.archive(other,result));assertEquals(clock.instant().plus(Duration.ofDays(7)),db.queryForObject("SELECT expires_at FROM files WHERE id=?",Timestamp.class,result).toInstant());}
    @Test void expiredOrReclaimedLeaseCannotChangeDatabaseOrFilesystem() throws Exception {resume();long before;try(var stream=Files.walk(filesRoot)){before=stream.filter(Files::isRegularFile).count();}var p=lease("DATA_EXPORT",Map.of("includeFiles",true));db.update("UPDATE tasks SET lease_token=? WHERE id=?",UUID.randomUUID().toString(),p.get("taskId"));assertEquals("TASK_LEASE_LOST",assertThrows(ApiProblem.class,()->worker.execute("DATA_EXPORT",owner,p)).code());db.update("UPDATE tasks SET lease_token=?,lease_until=? WHERE id=?",p.get("leaseToken"),Timestamp.from(clock.instant().minusSeconds(1)),p.get("taskId"));assertThrows(ApiProblem.class,()->worker.execute("DATA_EXPORT",owner,p));try(var stream=Files.walk(filesRoot)){assertEquals(before,stream.filter(Files::isRegularFile).count());}}
    @Test void restoreReplacesPrivateRecordsPreservesIdentityAndIncrementsVersions(){String r=resume();String kept=plan(owner,"备份中的任务"),otherPlan=plan(other,"其他账号任务"),backup=backup(true);var preview=preview(backup);db.update("UPDATE plan_tasks SET title='后来修改',version=5 WHERE id=?",kept);String removed=plan(owner,"备份之外");db.update("UPDATE users SET data_operation='IMPORTING' WHERE id=?",owner);db.update("UPDATE import_previews SET state='APPLYING' WHERE id=?",preview.get("id"));var p=lease("DATA_IMPORT",map("previewId",preview.get("id"),"dataRevision",0));worker.execute("DATA_IMPORT",owner,p);assertEquals("备份中的任务",db.queryForObject("SELECT title FROM plan_tasks WHERE id=?",String.class,kept));assertEquals(6,db.queryForObject("SELECT version FROM plan_tasks WHERE id=?",Integer.class,kept));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM plan_tasks WHERE id=?",Integer.class,removed));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM plan_tasks WHERE id=?",Integer.class,otherPlan));assertEquals("secret",db.queryForObject("SELECT password_hash FROM users WHERE id=?",String.class,owner));assertEquals(1,db.queryForObject("SELECT data_revision FROM users WHERE id=?",Integer.class,owner));assertEquals("APPLIED",db.queryForObject("SELECT state FROM import_previews WHERE id=?",String.class,preview.get("id")));String restoredFile=db.queryForObject("SELECT file_id FROM resumes WHERE id=?",String.class,r);assertArrayEquals("original".getBytes(),storage.read(owner+"/"+restoredFile+".bin",8,PrivateFileStorage.hash("original".getBytes())));var replay=rows.parse(db.queryForObject("SELECT payload FROM tasks WHERE id=?",String.class,p.get("taskId")));var retry=new LinkedHashMap<>((Map<String,Object>)replay);retry.put("taskId",p.get("taskId"));retry.put("leaseToken",p.get("leaseToken"));worker.execute("DATA_IMPORT",owner,retry);assertEquals(1,db.queryForObject("SELECT data_revision FROM users WHERE id=?",Integer.class,owner));}
    @Test void metadataOnlyBackupCannotRestoreMissingOriginal(){resume();String backup=backup(false);assertEquals("VALID",preview(backup).get("state"));db.update("UPDATE files SET state='PENDING_DELETE' WHERE purpose='RESUME'");var invalid=preview(backup);assertEquals("INVALID",invalid.get("state"));assertFalse(((List<?>)invalid.get("issues")).isEmpty());}
    @Test void staleRevisionCannotDestroyExistingData(){String id=plan(owner,"保留");String backup=backup(true);var preview=preview(backup);db.update("UPDATE users SET data_revision=1,data_operation='IMPORTING' WHERE id=?",owner);db.update("UPDATE import_previews SET state='APPLYING' WHERE id=?",preview.get("id"));var p=lease("DATA_IMPORT",map("previewId",preview.get("id"),"dataRevision",0));assertEquals("DATA_REVISION_CONFLICT",assertThrows(ApiProblem.class,()->worker.execute("DATA_IMPORT",owner,p)).code());assertEquals("保留",db.queryForObject("SELECT title FROM plan_tasks WHERE id=?",String.class,id));}
    @Test void resetDeletesOnlyPrivateWorkspaceAndUnlinksAvatarReference(){resume();plan(owner,"删除");plan(other,"保留");String avatar=file("AVATAR","avatar".getBytes());db.update("UPDATE users SET avatar_file_id=?,data_operation='RESETTING' WHERE id=?",avatar,owner);var p=lease("USER_ERASURE",map("mode","PRIVATE_ONLY","dataRevision",0));worker.execute("USER_ERASURE",owner,p);assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM resumes WHERE user_id=?",Integer.class,owner));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM plan_tasks WHERE user_id=?",Integer.class,other));assertEquals("ACTIVE",db.queryForObject("SELECT status FROM users WHERE id=?",String.class,owner));assertNull(db.queryForObject("SELECT avatar_file_id FROM users WHERE id=?",String.class,owner));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM files WHERE user_id=? AND state='READY'",Integer.class,owner));assertEquals("IDLE",db.queryForObject("SELECT data_operation FROM users WHERE id=?",String.class,owner));}
    @Test void accountErasureRemovesIdentityFilesAndAnonymizesPublishedContent() throws Exception {resume();plan(owner,"删除");String post=UUID.randomUUID().toString(),comment=UUID.randomUUID().toString(),room=UUID.randomUUID().toString(),task=UUID.randomUUID().toString();insert("posts",map("id",post,"author_id",owner,"body_md","公开内容","tags","[]","status","PUBLISHED"));insert("comments",map("id",comment,"post_id",post,"author_id",owner,"body","公开回复","status","PUBLISHED"));insert("buddy_rooms",map("id",room,"owner_id",owner,"name","房间","description","","visibility","PRIVATE","state","OPEN"));for(String user:List.of(owner,other))insert("buddy_members",map("id",UUID.randomUUID().toString(),"room_id",room,"user_id",user,"role",user.equals(owner)?"OWNER":"MEMBER","joined_at",Timestamp.from(clock.instant())));insert("buddy_tasks",map("id",task,"room_id",room,"title","题目"));insert("buddy_task_progress",map("id",UUID.randomUUID().toString(),"room_id",room,"task_id",task,"user_id",other));db.update("UPDATE users SET status='DELETING',data_operation='RESETTING' WHERE id=?",owner);var p=lease("USER_ERASURE",Map.of("mode","ACCOUNT"));worker.execute("USER_ERASURE",owner,p);assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM users WHERE id=?",Integer.class,owner));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM users WHERE id=?",Integer.class,other));assertNull(db.queryForObject("SELECT author_id FROM posts WHERE id=?",String.class,post));assertEquals("公开内容",db.queryForObject("SELECT body_md FROM posts WHERE id=?",String.class,post));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM buddy_rooms WHERE id=?",Integer.class,room));assertNull(db.queryForObject("SELECT user_id FROM tasks WHERE id=?",String.class,p.get("taskId")));assertFalse(db.queryForObject("SELECT dedup_key FROM tasks WHERE id=?",String.class,p.get("taskId")).contains(owner));try(var stream=Files.walk(filesRoot)){assertEquals(0,stream.filter(Files::isRegularFile).count());}}
    @Test void failedImportPreviewCanSafelyRetryOnlyAtOriginalRevision(){String original=plan(owner,"备份内容"),backup=backup(true);var view=preview(backup);db.update("UPDATE users SET data_operation='IMPORTING' WHERE id=?",owner);var p=lease("DATA_IMPORT",map("previewId",view.get("id"),"dataRevision",0));db.update("UPDATE import_previews SET state='APPLYING' WHERE id=?",view.get("id"));worker.onTerminalFailure("DATA_IMPORT",owner,p);assertEquals("INVALID",db.queryForObject("SELECT state FROM import_previews WHERE id=?",String.class,view.get("id")));db.update("UPDATE users SET data_operation='IDLE' WHERE id=?",owner);worker.execute("DATA_IMPORT",owner,p);assertEquals("APPLIED",db.queryForObject("SELECT state FROM import_previews WHERE id=?",String.class,view.get("id")));assertEquals("备份内容",db.queryForObject("SELECT title FROM plan_tasks WHERE id=?",String.class,original));}
    @Test void failedRestoreRollsBackRowsAndRemovesMovedFiles() throws Exception {
        String r=resume(),id=plan(owner,"备份任务"),backup=backup(true);var view=preview(backup);
        db.update("UPDATE plan_tasks SET title='当前任务' WHERE id=?",id);db.execute("ALTER TABLE plan_tasks ADD CONSTRAINT new_rule CHECK(title <> '备份任务')");db.update("UPDATE import_previews SET state='APPLYING' WHERE id=?",view.get("id"));db.update("UPDATE users SET data_operation='IMPORTING' WHERE id=?",owner);
        String originalFile=db.queryForObject("SELECT file_id FROM resumes WHERE id=?",String.class,r);long before;try(var stream=Files.walk(filesRoot)){before=stream.filter(Files::isRegularFile).count();}
        var p=lease("DATA_IMPORT",map("previewId",view.get("id"),"dataRevision",0));assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->worker.execute("DATA_IMPORT",owner,p));
        assertEquals("当前任务",db.queryForObject("SELECT title FROM plan_tasks WHERE id=?",String.class,id));assertEquals(originalFile,db.queryForObject("SELECT file_id FROM resumes WHERE id=?",String.class,r));assertEquals(0,db.queryForObject("SELECT data_revision FROM users WHERE id=?",Integer.class,owner));
        try(var stream=Files.walk(filesRoot)){assertEquals(before,stream.filter(Files::isRegularFile).count());}
    }
    @Test void restoreRespectsApplicationRoundCalendarReviewForeignKeyOrder(){
        String company=UUID.randomUUID().toString(),source=UUID.randomUUID().toString(),job=UUID.randomUUID().toString(),application=UUID.randomUUID().toString(),round=UUID.randomUUID().toString(),calendar=UUID.randomUUID().toString(),review=UUID.randomUUID().toString(),r=resume();
        insert("companies",map("id",company,"slug","test-company","name","公司","cities","[]","tags","[]","description_md",""));insert("sources",map("id",source,"name","来源","base_url","https://example.test","content_mode","METADATA_LINK","permission_note",""));
        insert("jobs",map("id",job,"company_id",company,"source_id",source,"title","岗位","role","后端","education","BACHELOR","recruitment_type","CAMPUS","skills","[]","description_md","","search_text","","canonical_url","https://example.test/job","canonical_url_hash","a".repeat(64),"deadline_precision","UNKNOWN","source_timezone","Asia/Shanghai","status","OPEN","collected_at",Timestamp.from(clock.instant())));
        insert("applications",map("id",application,"user_id",owner,"job_id",job,"resume_id",r,"sort_key",1,"notes",""));insert("interview_rounds",map("id",round,"user_id",owner,"application_id",application,"title","一面","round_type","TECHNICAL","sequence",1,"mode","ONLINE","status","SCHEDULED","timezone","Asia/Shanghai"));
        insert("calendar_events",map("id",calendar,"user_id",owner,"application_id",application,"round_id",round,"title","一面","kind","INTERVIEW","starts_at",Timestamp.from(clock.instant()),"ends_at",Timestamp.from(clock.instant().plusSeconds(3600)),"timezone","Asia/Shanghai","notes","","status","SCHEDULED"));
        insert("interview_reviews",map("id",review,"user_id",owner,"round_id",round,"recording_file_id",file("RECORDING","recording".getBytes()),"transcript","复盘","notes",""));String backup=backup(true);var view=preview(backup);assertEquals("VALID",view.get("state"));db.update("UPDATE import_previews SET state='APPLYING' WHERE id=?",view.get("id"));db.update("UPDATE users SET data_operation='IMPORTING' WHERE id=?",owner);worker.execute("DATA_IMPORT",owner,lease("DATA_IMPORT",map("previewId",view.get("id"),"dataRevision",0)));
        assertEquals(r,db.queryForObject("SELECT resume_id FROM applications WHERE id=?",String.class,application));assertEquals(round,db.queryForObject("SELECT round_id FROM calendar_events WHERE id=?",String.class,calendar));assertEquals("复盘",db.queryForObject("SELECT transcript FROM interview_reviews WHERE id=?",String.class,review));assertEquals(1,db.queryForObject("SELECT data_revision FROM users WHERE id=?",Integer.class,owner));
    }

    @Test void janitorDeletesOnlyOldUnreferencedObjectsAndHonorsActiveTasks() throws Exception {
        String r=resume(),original=db.queryForObject("SELECT file_id FROM resumes WHERE id=?",String.class,r);Path originalPath=filesRoot.resolve(owner).resolve(original+".bin");String orphanId=UUID.randomUUID().toString(),orphanKey=owner+"/"+orphanId+".bin";storage.move(storage.stage("orphan".getBytes()),orphanKey);Path orphan=filesRoot.resolve(orphanKey),staged=storage.stage("staged".getBytes());var old=java.nio.file.attribute.FileTime.from(clock.instant().minusSeconds(7200));for(Path path:List.of(originalPath,orphan,staged))Files.setLastModifiedTime(path,old);
        Path external=Files.createTempDirectory("private-cleanup-test-");Path protectedFile=external.resolve(UUID.randomUUID()+".bin");Files.writeString(protectedFile,"external");Files.setLastModifiedTime(protectedFile,old);Path linked=filesRoot.resolve(UUID.randomUUID().toString());Files.createSymbolicLink(linked,external);
        try{var p=lease("DATA_EXPORT",Map.of("includeFiles",true));worker.cleanupAbandonedFiles();assertTrue(Files.exists(orphan));assertTrue(Files.exists(staged));db.update("UPDATE tasks SET state='SUCCEEDED' WHERE id=?",p.get("taskId"));worker.cleanupAbandonedFiles();assertFalse(Files.exists(orphan));assertFalse(Files.exists(staged));assertTrue(Files.exists(originalPath));assertTrue(Files.exists(protectedFile));}finally{Files.deleteIfExists(linked);Files.deleteIfExists(protectedFile);Files.deleteIfExists(external);}
    }

    @Test void resetPurgesSensitiveMutationReplayButRetainsItsOwnReceipt(){
        var hashes=new OwnerTransactions(rows,new DataSourceTransactionManager((javax.sql.DataSource)db.getDataSource()));String secret="从旧简历缓存中清除的私人文字";
        insert("idempotency_records",map("id",UUID.randomUUID().toString(),"user_id",owner,"method","POST","route_hash",hashes.hash("/api/v1/resumes"),"idem_key",UUID.randomUUID().toString(),"request_hash","a".repeat(64),"http_status",201,"response_body",rows.json.writeValueAsString(Map.of("text",secret)),"expires_at",Timestamp.from(clock.instant().plusSeconds(86400))));
        String key=UUID.randomUUID().toString();var body=Map.<String,Object>of("confirm","RESET","dataRevision",0);var accepted=(Map<String,Object>)service.reset(owner,body,key,clock.millis()+60000);String id=accepted.get("id").toString(),token=UUID.randomUUID().toString();db.update("UPDATE tasks SET state='RUNNING',lease_token=?,lease_until=? WHERE id=?",token,Timestamp.from(clock.instant().plusSeconds(300)),id);var payload=new LinkedHashMap<>((Map<String,Object>)rows.parse(db.queryForObject("SELECT payload FROM tasks WHERE id=?",String.class,id)));payload.put("taskId",id);payload.put("leaseToken",token);worker.execute("USER_ERASURE",owner,payload);
        assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM idempotency_records WHERE user_id=?",Integer.class,owner));assertFalse(db.queryForObject("SELECT response_body FROM idempotency_records WHERE user_id=?",String.class,owner).contains(secret));var replay=(Map<String,Object>)service.reset(owner,body,key,clock.millis()+60000);assertEquals(id,replay.get("id"));assertEquals("IDLE",db.queryForObject("SELECT data_operation FROM users WHERE id=?",String.class,owner));assertDoesNotThrow(()->hashes.write(owner,"POST","/test-write",null,Map.of(),201,true,()->null));
    }

}
